using System;using System.Collections;using System.Text;using System.Web.Script.Serialization;using System.Collections.Generic;using System.Diagnostics;using System.IO;using System.Linq;using System.Runtime.InteropServices;
namespace PZ3D {static class LaunchJvmEnvironmentTests {
 static int checks;
 [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern IntPtr LoadLibraryW(string name);
 static void Check(bool value,string reason){if(!value)throw new Exception("FAIL "+reason);checks++;Console.WriteLine("PASS "+reason);}
 static string Quote(string value){return "\""+value.Replace("\"","\\\"")+"\"";}
 static int Loader(string game){foreach(string relative in new[]{"jre64/bin/server/jvm.dll","jre64/bin/instrument.dll"}){IntPtr module=LoadLibraryW(Path.Combine(game,relative));int error=module==IntPtr.Zero?Marshal.GetLastWin32Error():0;Console.WriteLine(relative+" loaded="+(module!=IntPtr.Zero)+" error="+error);if(module==IntPtr.Zero)return error;}foreach(string name in new[]{"jvm.dll","java.dll","instrument.dll","jli.dll"}){var module=Process.GetCurrentProcess().Modules.Cast<ProcessModule>().SingleOrDefault(row=>row.ModuleName.Equals(name,StringComparison.OrdinalIgnoreCase));string expected=Path.GetFullPath(Path.Combine(game,"jre64","bin",name=="jvm.dll"?"server/"+name:name));if(module==null||!Path.GetFullPath(module.FileName).Equals(expected,StringComparison.OrdinalIgnoreCase)){Console.WriteLine("foreign/missing module="+name+" actual="+(module==null?"missing":module.FileName));return 1;}Console.WriteLine("own module="+module.FileName);}return 0;}
 [DllImport("shell32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern IntPtr CommandLineToArgvW(string value,out int count);
 [DllImport("kernel32.dll")]static extern IntPtr LocalFree(IntPtr value);
 static string[] Arguments(ProcessStartInfo start){int count;IntPtr values=CommandLineToArgvW("probe "+start.Arguments,out count);if(values==IntPtr.Zero)throw new Exception("CommandLineToArgvW");try{return Enumerable.Range(1,count-1).Select(i=>Marshal.PtrToStringUni(Marshal.ReadIntPtr(values,i*IntPtr.Size))).ToArray();}finally{LocalFree(values);}}
 static Dictionary<string,object> Config(string[] arguments,string[] classpath,string main){return new Dictionary<string,object>{{"vmArgs",arguments},{"classpath",classpath},{"mainClass",main}};}
 static void WriteConfig(Engine engine,Dictionary<string,object> config){File.WriteAllText(engine.Config,new JavaScriptSerializer().Serialize(config),new UTF8Encoding(false));}
 static void WindowsBranches(){var config=Config(new[]{"-Dorder=root","-Xmx4g"},new[]{".","root.jar"},"Root/Main");config["windows"]=new Dictionary<string,object>{{"10.0.22000",new Dictionary<string,object>{{"vmArgs",new[]{"-Dorder=eleven"}}}},{"6.1",new Dictionary<string,object>{{"vmArgs",new[]{"-Dorder=seven"}}}},{"10.0.17134",new Dictionary<string,object>{{"vmArgs",new[]{"-Dorder=ten","-Xmx8g"}},{"mainClass","Wrong/Main"},{"classpath",new[]{"wrong.jar"}}}}};Check(LaunchProfiles.FrozenJavaArguments(config,new Version(6,1)).SequenceEqual(new[]{"-Dorder=root","-Xmx4g","-Dorder=seven","-cp",".;root.jar","Root.Main"}),"Windows 6.1 selects only its applicable branch after root arguments");Check(LaunchProfiles.FrozenJavaArguments(config,new Version(10,0,17134)).SequenceEqual(new[]{"-Dorder=root","-Xmx4g","-Dorder=ten","-Xmx8g","-cp",".;root.jar","Root.Main"}),"Windows 10 selects its highest applicable branch while root classpath and main retain precedence");Check(LaunchProfiles.FrozenJavaArguments(config,new Version(10,0,26300)).SequenceEqual(new[]{"-Dorder=root","-Xmx4g","-Dorder=eleven","-cp",".;root.jar","Root.Main"}),"Windows 11 selects the highest numerical build without merging lower branch arguments");Console.WriteLine("Windows actual="+LaunchProfiles.CurrentWindowsVersion()+" framework="+Environment.OSVersion.Version);Check(LaunchProfiles.CurrentWindowsVersion().Major>=Environment.OSVersion.Version.Major,"actual Windows version probe avoids framework compatibility version fallback on this host");}
 static void StartInfo(string root){string parent=Environment.GetEnvironmentVariable("PATH"),machine=Environment.GetEnvironmentVariable("PATH",EnvironmentVariableTarget.Machine),user=Environment.GetEnvironmentVariable("PATH",EnvironmentVariableTarget.User);foreach(string kind in new[]{"source","managed","frozen"}){
  var engine=new Engine(Path.Combine(root,kind,"game"),Path.Combine(root,kind,"user 中文"),Path.Combine(root,kind,"data"),true);Directory.CreateDirectory(engine.Game);if(kind=="managed")engine.ManagedVersion=true;if(kind=="frozen")engine.FrozenEnvironment=new SaveEnvironmentRecord();
  string[] common={"-javaagent:环境 agent.jar","-Dozl.environment="+Path.Combine(root,"中文 路径","environment.properties"),"-Dozl.quoted=前缀 \\\"quoted\\\" tail\\","-agentlib:zbNative","-javaagent:startup agent.jar","-Dozl.precedence=root"};
  var config=Config(common,new[]{".","中文 classpath.jar"},"ozl/tests/RootMain");config["windows"]=new Dictionary<string,object>{{"999.0",Config(new[]{"-Dozl.future=true"},new[]{"wrong-future.jar"},"wrong/FutureMain")},{LaunchProfiles.CurrentWindowsVersion().ToString(),Config(new[]{"-Dozl.precedence=branch","-Dozl.branch=当前 中文"},new[]{"wrong-branch.jar"},"wrong/BranchMain")},{"0.0",Config(new[]{"-Dozl.old=true"},new[]{"wrong-old.jar"},"wrong/OldMain")}};WriteConfig(engine,config);var start=LaunchProfiles.BuildStartInfo(engine);string expected=Path.Combine(Path.GetFullPath(engine.Game),"jre64","bin");Check(start.EnvironmentVariables["PATH"]==expected+";"+(parent??""),kind+" prepends only its own JRE bin and preserves every inherited PATH byte");
  if(kind=="frozen"){
   Check(start.FileName==Path.Combine(engine.Game,"jre64","bin","java.exe")&&start.CreateNoWindow&&start.WorkingDirectory==engine.Game&&!start.UseShellExecute,"frozen starts its own Java directly without a console window");
   string[] wanted=common.Concat(new[]{"-Dozl.precedence=branch","-Dozl.branch=当前 中文","-cp",".;中文 classpath.jar","ozl.tests.RootMain","-cachedir="+engine.User}).ToArray();Check(Arguments(start).SequenceEqual(wanted),"frozen preserves Unicode, spaces, quotes, agent order, root classpath/main and final cachedir; appends only the highest applicable Windows branch");
   config["windows"]=new Dictionary<string,object>{{"999.0",Config(new[]{"-Dozl.future=true"},new[]{"wrong.jar"},"wrong/Main")}};WriteConfig(engine,config);Check(Arguments(LaunchProfiles.BuildStartInfo(engine)).SequenceEqual(common.Concat(new[]{"-cp",".;中文 classpath.jar","ozl.tests.RootMain","-cachedir="+engine.User})),"no applicable Windows version retains only root VM arguments");config.Remove("windows");WriteConfig(engine,config);Check(Arguments(LaunchProfiles.BuildStartInfo(engine)).SequenceEqual(common.Concat(new[]{"-cp",".;中文 classpath.jar","ozl.tests.RootMain","-cachedir="+engine.User})),"missing Windows branches retain valid root configuration");
  }else{Check(start.FileName==Path.Combine(engine.Game,"ProjectZomboid64.exe")&&start.WorkingDirectory==engine.Game&&!start.UseShellExecute,kind+" retains native EXE, game working directory and direct process launch");Check(kind=="source"?string.IsNullOrEmpty(start.Arguments):Arguments(start).SequenceEqual(new[]{"-cachedir="+engine.User}),kind+" preserves existing cachedir argument behavior");}
  if(kind!="source")Check(start.EnvironmentVariables["SteamAppId"]=="108600"&&start.EnvironmentVariables["SteamGameId"]=="108600",kind+" retains independent-game Steam identity");
 }Check(Environment.GetEnvironmentVariable("PATH")==parent&&Environment.GetEnvironmentVariable("PATH",EnvironmentVariableTarget.Machine)==machine&&Environment.GetEnvironmentVariable("PATH",EnvironmentVariableTarget.User)==user,"building source, managed and frozen launch info changes neither parent, user nor machine PATH");}
 static void JavaArguments(string source,string classes,string root){
  string game=Path.Combine(root,"真实 JRE","game"),home=Path.Combine(root,"独立 中文 home"),manifest=Path.Combine(root,"环境 中文","environment.properties"),copy=Path.Combine(game,"jre64"),original=Path.Combine(source,"jre64");Directory.CreateDirectory(game);Directory.CreateDirectory(home);Directory.CreateDirectory(Path.GetDirectoryName(manifest));File.WriteAllText(manifest,"independent probe",Encoding.UTF8);foreach(string directory in Directory.EnumerateDirectories(original,"*",SearchOption.AllDirectories))Directory.CreateDirectory(Path.Combine(copy,directory.Substring(original.Length+1)));foreach(string file in Directory.EnumerateFiles(original,"*",SearchOption.AllDirectories))File.Copy(file,Path.Combine(copy,file.Substring(original.Length+1)));var engine=new Engine(game,Path.Combine(root,"实时 存档"),Path.Combine(root,"java-data"),true);engine.FrozenEnvironment=new SaveEnvironmentRecord();string quoted="中文 \\\"quoted\\\" tail\\";var config=Config(new[]{"-Duser.home="+home,"-Dozl.environment="+manifest,"-Dozl.quoted="+quoted,"-Dozl.precedence=root"},new[]{".",classes},"ozl/tests/LaunchArgumentProbe");config["windows"]=new Dictionary<string,object>{{LaunchProfiles.CurrentWindowsVersion().ToString(),new Dictionary<string,object>{{"vmArgs",new[]{"-Dozl.precedence=branch"}}}}};WriteConfig(engine,config);var start=LaunchProfiles.BuildStartInfo(engine);start.RedirectStandardOutput=start.RedirectStandardError=true;using(var process=Process.Start(start)){string output=process.StandardOutput.ReadToEnd(),error=process.StandardError.ReadToEnd();Check(process.WaitForExit(15000)&&process.ExitCode==0,"production frozen Java launch runs only the independent argument probe");Console.Write(error);var actual=output.Split(new[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries).Select(line=>line.Split(new[]{'='},2)).ToDictionary(pair=>pair[0],pair=>Encoding.UTF8.GetString(Convert.FromBase64String(pair[1])));Check(actual["user.home"]==home&&actual["ozl.environment"]==manifest&&actual["manifest"]=="independent probe","actual bundled JRE receives exact Chinese home/manifest paths and reads the intended file");Check(actual["ozl.quoted"]==quoted&&actual["ozl.precedence"]=="branch"&&actual["arg0"]=="-cachedir="+engine.User&&actual["argc"]=="1","actual bundled JRE preserves quoting, Windows override precedence and final Unicode cachedir");Check(actual["user.dir"]==game&&actual["java.class.path"]==".;"+classes,"actual bundled JRE uses the selected game working directory and root classpath");}
 }
 static void ActualLoader(string game,string root){game=Path.GetFullPath(game);string parent=Environment.GetEnvironmentVariable("PATH");string[] relative={"ProjectZomboid64.exe","ProjectZomboid64.json","jre64/bin/java.dll","jre64/bin/instrument.dll","jre64/bin/server/jvm.dll","jre64/bin/jli.dll"};var hashes=relative.ToDictionary(value=>value,value=>DlssInstaller.Hash(File.ReadAllBytes(Path.Combine(game,value))));var engine=new Engine(Path.Combine(root,"actual-game"),Path.Combine(root,"actual-user"),Path.Combine(root,"actual-data"),true);engine.Game=game;engine.FrozenEnvironment=new SaveEnvironmentRecord();var start=LaunchProfiles.BuildStartInfo(engine);Check(start.FileName==Path.Combine(game,"jre64","bin","java.exe")&&GameProcessGuard.ClassifyJavaCommandLine(Quote(start.FileName)+" "+start.Arguments)==JavaProcessRole.Client,"actual game JSON produces a frozen Java command recognized by existing client guards");Check(start.EnvironmentVariables["PATH"]==Path.Combine(game,"jre64","bin")+";"+(parent??""),"real JRE loader inherits the environment from production BuildStartInfo");start.FileName=typeof(LaunchJvmEnvironmentTests).Assembly.Location;start.Arguments="--loader "+Quote(game);start.CreateNoWindow=true;start.RedirectStandardOutput=start.RedirectStandardError=true;using(var child=Process.Start(start)){string output=child.StandardOutput.ReadToEnd(),error=child.StandardError.ReadToEnd();Check(child.WaitForExit(15000),"real JRE DLL loader exits without any game or Java main entry");Console.Write(output);Console.Write(error);Check(child.ExitCode==0,"real JRE jvm/instrument/java/jli all initialize from the selected game instead of a different installed JDK");}Check(relative.All(value=>hashes[value]==DlssInstaller.Hash(File.ReadAllBytes(Path.Combine(game,value)))),"actual native EXE, JSON and JRE DLL bytes stay unchanged");Check(Environment.GetEnvironmentVariable("PATH")==parent,"real DLL loader does not change its parent PATH");}
 public static int Main(string[] args){if(args.Length==2&&args[0]=="--loader")return Loader(args[1]);LauncherRuntime.Initialize();string root=Path.Combine(Path.GetTempPath(),"ozl-launch-jvm-快照-"+Guid.NewGuid().ToString("N"));try{StartInfo(root);WindowsBranches();string classes=Environment.GetEnvironmentVariable("OZL_LAUNCH_ARGUMENT_CLASSES");foreach(string game in args)ActualLoader(game,root);if(args.Length>0&&!string.IsNullOrEmpty(classes))JavaArguments(args[0],classes,root);Console.WriteLine("LAUNCH JVM ENVIRONMENT PASS: "+checks+" assertions");return 0;}catch(Exception error){Console.WriteLine(error);return 1;}finally{if(Directory.Exists(root))Directory.Delete(root,true);}}
}}
